// Naver Content MCP - single-file Cloudflare Worker build.
// Generated by scripts/bundle.mjs from src/*.js - edit those, not this.
// Paste into the Cloudflare dashboard editor (Workers > Create > Edit code).

// ======================================================================
// naver.js
// ======================================================================

/**
 * Naver scraping layer.
 *
 * Every read goes through a fallback chain so that one blocked route does not
 * take the whole server down. Failures are classified (blocked vs. parse vs.
 * transport) because "Naver said no" and "we could not find the body" need
 * very different fixes.
 */

const MOBILE_UA =
  "Mozilla/5.0 (Linux; Android 14; SM-S928N) AppleWebKit/537.36 (KHTML, like Gecko) " +
  "Chrome/126.0.6478.122 Mobile Safari/537.36";

/** Headers copied from a real mobile Chrome navigation request. */
function baseHeaders(referer) {
  const h = {
    "User-Agent": MOBILE_UA,
    Accept:
      "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
    "Accept-Language": "ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7",
    "Upgrade-Insecure-Requests": "1",
    "Sec-Ch-Ua": '"Chromium";v="126", "Google Chrome";v="126", "Not-A.Brand";v="99"',
    "Sec-Ch-Ua-Mobile": "?1",
    "Sec-Ch-Ua-Platform": '"Android"',
    "Sec-Fetch-Dest": "document",
    "Sec-Fetch-Mode": "navigate",
    "Sec-Fetch-Site": referer ? "same-origin" : "none",
    "Sec-Fetch-User": "?1",
  };
  if (referer) h.Referer = referer;
  return h;
}

const BLOCK_SIGNS = [
  "많은 요청이 있습니다",
  "비정상적인 접근",
  "자동입력 방지",
  "captcha",
  "이용이 제한",
  "접근이 차단",
  "일시적으로 제한",
];

class NaverError extends Error {
  constructor(kind, message, detail) {
    super(message);
    this.kind = kind; // BLOCKED | PARSE_FAILED | NOT_FOUND | TRANSPORT | UPSTREAM
    this.detail = detail || null;
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * Single HTTP GET with retry. Workers' fetch decompresses gzip transparently.
 * Retries 429/403/5xx with exponential backoff; those are usually rate limits
 * rather than hard bans.
 */
async function httpGet(url, { referer, timeoutMs = 15000, retries = 2 } = {}) {
  let lastErr = null;

  for (let attempt = 0; attempt <= retries; attempt++) {
    if (attempt > 0) await sleep(400 * 2 ** (attempt - 1) + Math.floor(Math.random() * 250));

    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), timeoutMs);
    try {
      const resp = await fetch(url, {
        headers: baseHeaders(referer),
        redirect: "follow",
        signal: ctl.signal,
        cf: { cacheTtl: 0, cacheEverything: false },
      });
      const text = await resp.text();

      if (resp.status === 429 || resp.status === 403) {
        lastErr = new NaverError("BLOCKED", `Naver returned HTTP ${resp.status}`, { url, status: resp.status });
        continue;
      }
      if (resp.status >= 500) {
        lastErr = new NaverError("UPSTREAM", `Naver returned HTTP ${resp.status}`, { url, status: resp.status });
        continue;
      }
      if (resp.status === 404) {
        throw new NaverError("NOT_FOUND", "Page does not exist (HTTP 404)", { url });
      }
      if (!resp.ok) {
        throw new NaverError("UPSTREAM", `Unexpected HTTP ${resp.status}`, { url, status: resp.status });
      }

      const low = text.toLowerCase();
      const sign = BLOCK_SIGNS.find((s) => low.includes(s.toLowerCase()));
      if (sign && text.length < 20000) {
        lastErr = new NaverError("BLOCKED", `Naver served a block page (${sign})`, { url });
        continue;
      }
      return text;
    } catch (e) {
      clearTimeout(timer);
      if (e instanceof NaverError && e.kind === "NOT_FOUND") throw e;
      lastErr =
        e instanceof NaverError
          ? e
          : new NaverError("TRANSPORT", `Request failed: ${e.message}`, { url });
    } finally {
      clearTimeout(timer);
    }
  }
  throw lastErr || new NaverError("TRANSPORT", "Request failed with no further detail", { url });
}

/* ------------------------------------------------------------------ HTML */

const SCRIPT_RE = /<(script|style|noscript)[^>]*>[\s\S]*?<\/\1>/gi;
const BLOCK_END_RE = /<\/(p|div|li|h[1-6]|blockquote|tr)>|<br\s*\/?>/gi;

const ENTITIES = {
  "&nbsp;": " ", "&amp;": "&", "&lt;": "<", "&gt;": ">",
  "&quot;": '"', "&#39;": "'", "&apos;": "'", "&middot;": "·",
};

function htmlToText(html) {
  let s = String(html || "").replace(SCRIPT_RE, " ").replace(BLOCK_END_RE, "\n");
  s = s.replace(/<[^>]+>/g, " ");
  for (const [k, v] of Object.entries(ENTITIES)) s = s.split(k).join(v);
  s = s.replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)));
  return s
    .split("\n")
    .map((ln) => ln.replace(/[ \t​ ]+/g, " ").trim())
    .filter(Boolean)
    .join("\n")
    .replace(/\n{3,}/g, "\n\n");
}

function decodeEntities(s) {
  let out = String(s || "");
  for (const [k, v] of Object.entries(ENTITIES)) out = out.split(k).join(v);
  return out.replace(/<[^>]+>/g, "").trim();
}

/**
 * SmartEditor ONE first, then the older layouts. Returns null when no
 * container matched so the caller can try the next fallback route.
 */
const CONTAINERS = [
  ["se-main-container", /<div[^>]*class="[^"]*se-main-container[^"]*"[^>]*>([\s\S]*)/i],
  ["postViewArea", /<div[^>]*id="postViewArea"[^>]*>([\s\S]*)/i],
  ["post-view", /<div[^>]*class="[^"]*post-view[^"]*"[^>]*>([\s\S]*)/i],
  ["__content", /<div[^>]*id="__content"[^>]*>([\s\S]*)/i],
  ["se_component_wrap", /<div[^>]*class="[^"]*se_component_wrap[^"]*"[^>]*>([\s\S]*)/i],
];

function extractPostBody(html) {
  for (const [name, re] of CONTAINERS) {
    const m = html.match(re);
    if (!m) continue;
    // Cut at known post-body boundaries to avoid swallowing comments/footer.
    let chunk = m[1];
    const stop = chunk.search(
      /<div[^>]*class="[^"]*(?:se-lastLine|area_comment|post_footer|floating_menu|btn_recommend)/i
    );
    if (stop > 200) chunk = chunk.slice(0, stop);
    const text = htmlToText(chunk);
    if (text.length > 80) return { strategy: name, text };
  }
  return null;
}

function extractTitle(html) {
  const pats = [
    /<meta[^>]+property="og:title"[^>]+content="([^"]+)"/i,
    /<div[^>]*class="[^"]*se-title-text[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<h3[^>]*class="[^"]*se_textarea[^"]*"[^>]*>([\s\S]*?)<\/h3>/i,
    /<title>([\s\S]*?)<\/title>/i,
  ];
  for (const p of pats) {
    const m = html.match(p);
    if (m) {
      const t = decodeEntities(m[1]);
      if (t) return t.replace(/\s*:\s*네이버\s*블로그\s*$/, "").trim();
    }
  }
  return "";
}

function extractDate(html) {
  const pats = [
    /<span[^>]*class="[^"]*se_publishDate[^"]*"[^>]*>([\s\S]*?)<\/span>/i,
    /<p[^>]*class="[^"]*se_publishDate[^"]*"[^>]*>([\s\S]*?)<\/p>/i,
    /<span[^>]*class="[^"]*_postAddDate[^"]*"[^>]*>([\s\S]*?)<\/span>/i,
    /<meta[^>]+property="article:published_time"[^>]+content="([^"]+)"/i,
  ];
  for (const p of pats) {
    const m = html.match(p);
    if (m) {
      const d = decodeEntities(m[1]);
      if (d) return d;
    }
  }
  return "";
}

/* ------------------------------------------------------------- URL utils */

/** blog.naver.com renders the body inside an iframe, so normalise to m.blog. */
function parseBlogUrl(url) {
  const s = String(url || "").trim();
  let m = s.match(/blog\.naver\.com\/([A-Za-z0-9_-]+)\/(\d{6,})/);
  if (m) return { blogId: m[1], logNo: m[2] };

  m = s.match(/[?&]blogId=([A-Za-z0-9_-]+)/);
  const n = s.match(/[?&]logNo=(\d{6,})/);
  if (m && n) return { blogId: m[1], logNo: n[1] };

  m = s.match(/blog\.naver\.com\/([A-Za-z0-9_-]+)\/?$/);
  if (m) return { blogId: m[1], logNo: null };

  return null;
}

function parseNewsUrl(url) {
  const s = String(url || "").trim();
  const m = s.match(/news\.naver\.com\/(?:mnews\/)?article\/(\d{3})\/(\d{10})/) ||
            s.match(/[?&]oid=(\d{3})[^]*?[?&]aid=(\d{10})/);
  return m ? { oid: m[1], aid: m[2] } : null;
}

/* --------------------------------------------------------- fallback chain */

/**
 * Ordered blog-read routes. The default order is set from the step-0 probe;
 * every route stays in the chain so a future block on one path degrades
 * instead of breaking.
 */
function blogReadRoutes(blogId, logNo) {
  return [
    {
      name: "direct-mobile",
      url: `https://m.blog.naver.com/${blogId}/${logNo}`,
      referer: "https://m.search.naver.com/",
      parse: (html) => {
        const body = extractPostBody(html);
        if (!body) return null;
        return { title: extractTitle(html), date: extractDate(html), ...body };
      },
    },
    {
      name: "pc-postview",
      url:
        `https://blog.naver.com/PostView.naver?blogId=${blogId}&logNo=${logNo}` +
        `&redirect=Dlog&widgetTypeCall=true&directAccess=false`,
      referer: `https://blog.naver.com/${blogId}`,
      parse: (html) => {
        const body = extractPostBody(html);
        if (!body) return null;
        return { title: extractTitle(html), date: extractDate(html), ...body };
      },
    },
    {
      name: "jina-reader",
      url: `https://r.jina.ai/https://m.blog.naver.com/${blogId}/${logNo}`,
      referer: null,
      timeoutMs: 40000,
      parse: (md) => {
        if (!md || md.length < 200) return null;
        // r.jina.ai returns markdown with a "Title:" preamble.
        const t = md.match(/^Title:\s*(.+)$/m);
        const body = md.replace(/^(Title|URL Source|Published Time|Markdown Content):.*$/gm, "").trim();
        if (body.length < 120) return null;
        return { strategy: "jina-markdown", title: t ? t[1].trim() : "", date: "", text: body };
      },
    },
    {
      name: "rss",
      url: `https://rss.blog.naver.com/${blogId}.xml`,
      referer: null,
      parse: (xml) => {
        // RSS only carries recent posts; match the requested one if present.
        const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/gi)].map((m) => m[1]);
        const hit = items.find((it) => it.includes(String(logNo))) || null;
        if (!hit) return null;
        const pick = (tag) => {
          const m = hit.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, "i"));
          return m ? decodeEntities(m[1].replace(/<!\[CDATA\[|\]\]>/g, "")) : "";
        };
        const text = htmlToText(pick("description"));
        if (text.length < 80) return null;
        return { strategy: "rss-description", title: pick("title"), date: pick("pubDate"), text };
      },
    },
  ];
}

/**
 * Walk the chain and return the first usable result, along with a per-route
 * trace so callers can report exactly what happened.
 */
async function readViaChain(routes, order) {
  const ordered = order
    ? order.map((n) => routes.find((r) => r.name === n)).filter(Boolean)
    : routes;
  const chain = ordered.length ? ordered : routes;
  const trace = [];

  for (const route of chain) {
    try {
      const raw = await httpGet(route.url, {
        referer: route.referer,
        timeoutMs: route.timeoutMs || 15000,
        retries: 1,
      });
      const parsed = route.parse(raw);
      if (!parsed) {
        trace.push({ route: route.name, result: "PARSE_FAILED", bytes: raw.length });
        continue;
      }
      trace.push({ route: route.name, result: "OK", chars: parsed.text.length });
      return { ...parsed, route: route.name, trace };
    } catch (e) {
      trace.push({
        route: route.name,
        result: e instanceof NaverError ? e.kind : "TRANSPORT",
        message: e.message,
      });
    }
  }

  const blocked = trace.filter((t) => t.result === "BLOCKED").length;
  const kind = blocked === trace.length ? "BLOCKED" : "PARSE_FAILED";
  const err = new NaverError(
    kind,
    kind === "BLOCKED"
      ? "All routes were blocked by Naver."
      : "Reached Naver but could not extract a post body on any route.",
    { trace }
  );
  throw err;
}

// ======================================================================
// tools.js
// ======================================================================

/**
 * The five MCP tools. Each returns markdown-ish plain text, and each failure
 * says whether Naver refused us or whether we simply could not parse what it
 * sent - those need different fixes, so they must not look alike.
 */


const SEARCH_REFERER = "https://m.search.naver.com/";
const MAX_COUNT = 100;
const PAGE_SIZE = 30;

const clampCount = (n, dflt = 10) => {
  const v = Number.isFinite(Number(n)) ? Math.floor(Number(n)) : dflt;
  return Math.min(MAX_COUNT, Math.max(1, v));
};

// Long posts otherwise dominate the caller's context. Most posts land well
// under this, so the cap costs nothing in the common case.
const DEFAULT_MAX_CHARS = 8000;

/**
 * Trim body text to a character budget, cutting at a paragraph break so the
 * tail is not left mid-sentence. Truncation is always announced - silently
 * dropping half a post would let a caller summarise it as if it were whole.
 */
function capLength(text, maxChars) {
  const limit = Number.isFinite(Number(maxChars)) ? Math.floor(Number(maxChars)) : DEFAULT_MAX_CHARS;
  if (limit <= 0 || text.length <= limit) return { text, truncated: false };

  let cut = text.lastIndexOf("\n", limit);
  if (cut < limit * 0.6) cut = limit; // no usable break; take the hard cut
  const kept = text.slice(0, cut).trimEnd();
  return {
    text:
      `${kept}\n\n---\n[본문이 길어 ${kept.length}/${text.length}자만 표시했습니다. ` +
      `전체가 필요하면 max_chars 를 늘리거나 0(무제한)으로 호출하세요.]`,
    truncated: true,
  };
}


// UI chrome that appears as link text on result pages and is never a title.
const UI_NOISE = [
  "저장하기", "Keep에 저장", "Keep 바로가기", "공유하기", "더보기", "신고",
  "답글", "댓글", "관련글", "본문 보기", "바로가기", "옵션", "닫기", "열기",
  "길찾기", "예약", "전화",
];

const isNoise = (t) =>
  !t || t.length < 4 || t.length > 200 || UI_NOISE.some((n) => t.includes(n)) ||
  /^[\s·|\-—RE]*$/.test(t);

const cleanTitle = (raw) => {
  const t = htmlToText(raw).replace(/\s+/g, " ").trim();
  return isNoise(t) ? "" : t;
};

/**
 * Collect search hits, preferring anchors whose href is the result URL.
 *
 * The first occurrence of a result URL on the page is Keep's save button
 * (`data-url="…"`), whose only text is "문서 저장하기" — so anything that
 * searches by proximity to the URL finds the button, not the title. Matching
 * `<a href="…">` skips the button and lands on the real title anchor.
 *
 * A second pass over bare URLs then picks up anything that only appears in an
 * attribute, so coverage never drops below what a plain URL scan would find;
 * those hits simply carry no title.
 */
function collectHits(html, urlSource, into, want) {
  const { anchor, bare, key } = urlSource;

  anchor.lastIndex = 0;
  let m;
  while ((m = anchor.exec(html)) !== null && into.size < want) {
    const k = key(m);
    const title = cleanTitle(m[m.length - 1]);
    const prev = into.get(k);
    // The same URL appears in several anchors ("더보기", the snippet, the
    // title). Let a later real title replace an earlier empty one instead of
    // letting whichever came first win.
    if (prev && (prev.title || !title)) continue;
    into.set(k, { title });
  }

  bare.lastIndex = 0;
  while ((m = bare.exec(html)) !== null && into.size < want) {
    const k = key(m);
    if (into.has(k)) continue;
    into.set(k, { title: "" });
  }
  return into;
}

/** Regexes for one result type: title-bearing anchors, then bare URLs. */
function urlSource(pattern, keyFn) {
  return {
    anchor: new RegExp(`<a\\b[^>]*\\bhref="(?:${pattern})[^"]*"[^>]*>([\\s\\S]{0,2500}?)</a>`, "gi"),
    bare: new RegExp(pattern, "gi"),
    key: keyFn,
  };
}

const BLOG_PATTERN = "https?://(?:m\\.)?blog\\.naver\\.com/([A-Za-z0-9_-]+)/(\\d{6,})";
const CAFE_PATTERN = "https?://cafe\\.naver\\.com/([A-Za-z0-9_-]+)/(\\d{2,})";
const NEWS_PATTERN = "https?://n\\.news\\.naver\\.com/(?:mnews/)?article/(\\d{3})/(\\d{10})";

const pairKey = (m) => `${m[1]}/${m[2]}`;

/* -------------------------------------------------------------- 1. blog search */

async function naverBlogSearch({ query, count = 10, sort = "sim" }) {
  if (!query || !String(query).trim()) {
    throw new NaverError("BAD_INPUT", "query is required");
  }
  const want = clampCount(count);
  const sortParam = sort === "date" ? "&nso=so%3Add%2Cp%3Aall" : "";
  const src = urlSource(BLOG_PATTERN, pairKey);
  const seen = new Map();

  for (let start = 1; seen.size < want && start <= 91; start += PAGE_SIZE) {
    const url =
      `https://m.search.naver.com/search.naver?ssc=tab.m_blog.all&sm=mtb_jum` +
      `&query=${encodeURIComponent(query)}&start=${start}${sortParam}`;
    const html = await httpGet(url, { referer: SEARCH_REFERER });

    const before = seen.size;
    collectHits(html, src, seen, want);
    if (seen.size === before) break; // page added nothing new
    if (seen.size < want) await sleep(600); // be polite between pages
  }

  const items = [...seen.entries()].slice(0, want).map(([key, v]) => ({
    url: `https://m.blog.naver.com/${key}`,
    title: v.title,
  }));
  if (!items.length) {
    throw new NaverError("PARSE_FAILED", "Search page loaded but no blog posts were found in it.", { query });
  }

  const lines = items.map(
    (it, i) => `${i + 1}. ${it.title || "(제목 미확인)"}\n   ${it.url}`
  );
  return `"${query}" 블로그 검색 결과 ${items.length}건 (정렬: ${sort})\n\n${lines.join("\n")}`;
}

/* ---------------------------------------------------------------- 2. blog read */

async function naverBlogRead({ url, max_chars }) {
  const ref = parseBlogUrl(url);
  if (!ref || !ref.logNo) {
    throw new NaverError(
      "BAD_INPUT",
      "Could not read a blogId/logNo out of that URL. Expected something like https://blog.naver.com/{blogId}/{logNo}.",
      { url }
    );
  }

  const routes = blogReadRoutes(ref.blogId, ref.logNo);
  const post = await readViaChain(routes, DEFAULT_BLOG_ORDER);

  const header = [
    post.title ? `# ${post.title}` : `# ${ref.blogId}/${ref.logNo}`,
    `출처: https://m.blog.naver.com/${ref.blogId}/${ref.logNo}`,
    post.date ? `작성일: ${post.date}` : null,
    `경로: ${post.route} (추출: ${post.strategy})`,
  ]
    .filter(Boolean)
    .join("\n");

  const body = capLength(post.text, max_chars);
  return `${header}\n\n---\n\n${body.text}`;
}

/**
 * Preference order measured by the step-0 probe. All four stay in the chain;
 * this only decides what is tried first.
 */
const DEFAULT_BLOG_ORDER = ["direct-mobile", "pc-postview", "jina-reader", "rss"];

/* -------------------------------------------------------------- 3. news search */

async function naverNewsSearch({ query, count = 10 }) {
  if (!query || !String(query).trim()) {
    throw new NaverError("BAD_INPUT", "query is required");
  }
  const want = clampCount(count);
  const src = urlSource(NEWS_PATTERN, pairKey);
  const seen = new Map();

  for (let start = 1; seen.size < want && start <= 91; start += PAGE_SIZE) {
    const url =
      `https://m.search.naver.com/search.naver?ssc=tab.m_news.all&where=m_news` +
      `&query=${encodeURIComponent(query)}&start=${start}`;
    const html = await httpGet(url, { referer: SEARCH_REFERER });

    const before = seen.size;
    collectHits(html, src, seen, want);
    if (seen.size === before) break;
    if (seen.size < want) await sleep(600);
  }

  const items = [...seen.entries()].slice(0, want).map(([key, v]) => ({
    url: `https://n.news.naver.com/mnews/article/${key}`,
    title: v.title,
  }));
  if (!items.length) {
    throw new NaverError("PARSE_FAILED", "News search page loaded but no articles were found in it.", { query });
  }
  const lines = items.map((it, i) => `${i + 1}. ${it.title || "(제목 미확인)"}\n   ${it.url}`);
  return `"${query}" 뉴스 검색 결과 ${items.length}건\n\n${lines.join("\n")}`;
}

/* ---------------------------------------------------------------- 4. news read */

const NEWS_BODY = [
  /<article[^>]*id="dic_area"[^>]*>([\s\S]*?)<\/article>/i,
  /<div[^>]*id="dic_area"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/i,
  /<div[^>]*id="newsct_article"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/i,
  /<div[^>]*class="[^"]*newsct_article[^"]*"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/i,
];

async function naverNewsRead({ url, max_chars }) {
  const ref = parseNewsUrl(url);
  if (!ref) {
    throw new NaverError(
      "BAD_INPUT",
      "Could not read oid/aid out of that URL. Expected https://n.news.naver.com/mnews/article/{oid}/{aid}.",
      { url }
    );
  }
  const target = `https://n.news.naver.com/mnews/article/${ref.oid}/${ref.aid}`;
  const html = await httpGet(target, { referer: SEARCH_REFERER });

  let body = "";
  for (const re of NEWS_BODY) {
    const m = html.match(re);
    if (m) {
      body = htmlToText(m[1]);
      if (body.length > 80) break;
    }
  }
  if (!body || body.length < 80) {
    throw new NaverError(
      "PARSE_FAILED",
      "Fetched the article page but no known body container matched.",
      { url: target, bytes: html.length }
    );
  }

  const title = extractTitle(html);
  const press =
    (html.match(/<meta[^>]+property="og:site_name"[^>]+content="([^"]+)"/i) || [])[1] || "";
  const date =
    (html.match(/<span[^>]*class="[^"]*media_end_head_info_datestamp_time[^"]*"[^>]*data-date-time="([^"]+)"/i) || [])[1] ||
    extractDate(html);

  const header = [
    title ? `# ${title}` : `# ${ref.oid}/${ref.aid}`,
    press ? `언론사: ${press}` : null,
    date ? `작성일: ${date}` : null,
    `출처: ${target}`,
  ]
    .filter(Boolean)
    .join("\n");

  return `${header}\n\n---\n\n${capLength(body, max_chars).text}`;
}

/* -------------------------------------------------------------- 5. cafe search */

async function naverCafeSearch({ query, count = 10 }) {
  if (!query || !String(query).trim()) {
    throw new NaverError("BAD_INPUT", "query is required");
  }
  const want = clampCount(count);
  // Only public cafe article links; member-only boards are not reachable
  // without a login and are deliberately not attempted.
  const src = urlSource(CAFE_PATTERN, pairKey);
  const seen = new Map();

  for (let start = 1; seen.size < want && start <= 91; start += PAGE_SIZE) {
    const url =
      `https://m.search.naver.com/search.naver?ssc=tab.m_cafe.all&where=m_cafe` +
      `&query=${encodeURIComponent(query)}&start=${start}`;
    const html = await httpGet(url, { referer: SEARCH_REFERER });

    const before = seen.size;
    collectHits(html, src, seen, want);
    if (seen.size === before) break;
    if (seen.size < want) await sleep(600);
  }

  const items = [...seen.entries()].slice(0, want).map(([key, v]) => ({
    url: `https://cafe.naver.com/${key}`,
    cafe: key.split("/")[0],
    title: v.title,
  }));
  if (!items.length) {
    throw new NaverError(
      "PARSE_FAILED",
      "Cafe search page loaded but no public cafe posts were found. Member-only posts are not accessible without a login.",
      { query }
    );
  }
  const lines = items.map(
    (it, i) => `${i + 1}. ${it.title || "(제목 미확인)"}\n   카페: ${it.cafe}\n   ${it.url}`
  );
  return `"${query}" 카페 검색 결과 ${items.length}건 (공개글만)\n\n${lines.join("\n")}`;
}

/* ------------------------------------------------------------ 6. place reviews */

async function naverPlaceReviews({ query, count = 10 }) {
  if (!query || !String(query).trim()) {
    throw new NaverError("BAD_INPUT", "query is required");
  }
  const want = clampCount(count);

  // Place "blog reviews" are ordinary blog posts about the place, so the most
  // reliable route is the blog tab scoped by the place name plus 리뷰/후기.
  const url =
    `https://m.search.naver.com/search.naver?ssc=tab.m_blog.all` +
    `&query=${encodeURIComponent(query + " 후기")}&start=1`;
  const html = await httpGet(url, { referer: SEARCH_REFERER });

  const seen = collectHits(html, urlSource(BLOG_PATTERN, pairKey), new Map(), want);

  const placeIds = [
    ...new Set(
      (html.match(/place\.naver\.com\/(?:restaurant|place)\/(\d+)/g) || []).map((s) =>
        s.replace(/\D+/g, "")
      )
    ),
  ].slice(0, 3);

  const items = [...seen.entries()].slice(0, want).map(([key, v]) => ({
    url: `https://m.blog.naver.com/${key}`,
    title: v.title,
  }));
  if (!items.length) {
    throw new NaverError("PARSE_FAILED", "No blog reviews were found for that place.", { query });
  }

  const lines = items.map((it, i) => `${i + 1}. ${it.title || "(제목 미확인)"}\n   ${it.url}`);
  const placeLine = placeIds.length
    ? `\n\n플레이스 페이지: ${placeIds.map((id) => `https://m.place.naver.com/restaurant/${id}/review/ugc`).join(", ")}`
    : "";
  return (
    `"${query}" 플레이스 블로그 리뷰 ${items.length}건\n\n${lines.join("\n")}` +
    placeLine +
    `\n\n(본문을 읽으려면 naver_blog_read 에 위 URL을 넣으세요.)`
  );
}

// ======================================================================
// index.js
// ======================================================================

/**
 * Authless remote MCP server for Naver content, on Cloudflare Workers.
 *
 * Speaks the Streamable HTTP transport that Claude's custom connectors use:
 * JSON-RPC 2.0 over POST, plus a GET SSE endpoint for clients that open one.
 * No auth, no API keys - Naver's public pages are scraped from the edge.
 */



const SERVER_INFO = { name: "naver-content-mcp", version: "1.0.0" };
const SUPPORTED_PROTOCOLS = ["2025-06-18", "2025-03-26", "2024-11-05"];
const DEFAULT_PROTOCOL = "2025-06-18";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Accept, Mcp-Session-Id, MCP-Protocol-Version, Authorization",
  "Access-Control-Expose-Headers": "Mcp-Session-Id",
  "Access-Control-Max-Age": "86400",
};

const TOOLS = [
  {
    name: "naver_blog_search",
    description:
      "네이버 블로그를 검색해 글 목록(제목 + URL)을 돌려준다. 본문이 필요하면 결과 URL을 naver_blog_read 에 넣어라. 네이버 오픈 API가 아니라 모바일 검색 페이지를 직접 스크랩한다.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "검색어 (한국어 권장)" },
        count: { type: "integer", description: "가져올 개수 (1-100, 기본 10)", minimum: 1, maximum: 100 },
        sort: { type: "string", enum: ["sim", "date"], description: "sim=정확도순(기본), date=최신순" },
      },
      required: ["query"],
    },
  },
  {
    name: "naver_blog_read",
    description:
      "네이버 블로그 글 하나의 본문 전체를 마크다운으로 읽어온다. blog.naver.com URL은 iframe 구조라 본문이 안 나오므로 자동으로 m.blog.naver.com 으로 변환해 요청한다. 스마트에디터 ONE(se-main-container)을 우선 처리하고 구버전 레이아웃도 폴백으로 지원한다.",
    inputSchema: {
      type: "object",
      properties: {
        url: {
          type: "string",
          description: "블로그 글 URL. blog.naver.com / m.blog.naver.com / PostView 링크 모두 가능",
        },
        max_chars: {
          type: "integer",
          description:
            "본문 최대 글자수 (기본 8000). 컨텍스트를 아끼려면 2000~3000, 전체가 필요하면 0(무제한). 잘린 경우 응답에 명시된다.",
          minimum: 0,
        },
      },
      required: ["url"],
    },
  },
  {
    name: "naver_news_search",
    description: "네이버 뉴스를 검색해 기사 목록(제목 + URL)을 돌려준다. 본문은 naver_news_read 로 읽는다.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "검색어" },
        count: { type: "integer", description: "가져올 개수 (1-100, 기본 10)", minimum: 1, maximum: 100 },
      },
      required: ["query"],
    },
  },
  {
    name: "naver_news_read",
    description: "네이버 뉴스 기사 하나의 본문 전체를 읽어온다 (n.news.naver.com 기사 URL).",
    inputSchema: {
      type: "object",
      properties: {
        url: { type: "string", description: "네이버 뉴스 기사 URL" },
        max_chars: {
          type: "integer",
          description: "본문 최대 글자수 (기본 8000, 0이면 무제한). 잘린 경우 응답에 명시된다.",
          minimum: 0,
        },
      },
      required: ["url"],
    },
  },
  {
    name: "naver_cafe_search",
    description:
      "네이버 카페의 공개 글을 검색해 목록을 돌려준다. 로그인이 필요한 회원 전용 글은 접근하지 않는다.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "검색어" },
        count: { type: "integer", description: "가져올 개수 (1-100, 기본 10)", minimum: 1, maximum: 100 },
      },
      required: ["query"],
    },
  },
  {
    name: "naver_place_reviews",
    description:
      "네이버 플레이스(장소)에 대한 블로그 리뷰 글 목록을 돌려준다. 맛집/카페/숙소 후기를 모을 때 쓴다.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "장소명 (예: '성수동 카페', '제주 흑돼지')" },
        count: { type: "integer", description: "가져올 개수 (1-100, 기본 10)", minimum: 1, maximum: 100 },
      },
      required: ["query"],
    },
  },
];

const HANDLERS = {
  naver_blog_search: naverBlogSearch,
  naver_blog_read: naverBlogRead,
  naver_news_search: naverNewsSearch,
  naver_news_read: naverNewsRead,
  naver_cafe_search: naverCafeSearch,
  naver_place_reviews: naverPlaceReviews,
};

/** Turn an internal error into text that tells the model what to do next. */
function describeFailure(err) {
  if (err instanceof NaverError) {
    const hint =
      {
        BLOCKED:
          "네이버가 요청을 거부했습니다(차단/레이트리밋). 파싱 실패가 아닙니다. 잠시 후 다시 시도하거나 다른 글을 시도하세요.",
        PARSE_FAILED:
          "네이버 페이지는 정상적으로 받았지만 본문 영역을 찾지 못했습니다. 차단이 아니라 레이아웃 문제입니다.",
        NOT_FOUND: "해당 글이 존재하지 않거나 삭제/비공개 상태입니다.",
        BAD_INPUT: "입력값이 올바르지 않습니다.",
        TRANSPORT: "네트워크 요청 자체가 실패했습니다.",
        UPSTREAM: "네이버 서버가 오류를 반환했습니다.",
      }[err.kind] || "알 수 없는 오류입니다.";

    let out = `[${err.kind}] ${err.message}\n\n→ ${hint}`;
    if (err.detail?.trace) {
      out += `\n\n시도한 경로:\n${err.detail.trace
        .map((t) => `  - ${t.route}: ${t.result}${t.message ? ` (${t.message})` : ""}`)
        .join("\n")}`;
    }
    return out;
  }
  return `[INTERNAL] ${err?.message || String(err)}`;
}

async function callTool(name, args) {
  const fn = HANDLERS[name];
  if (!fn) {
    return { content: [{ type: "text", text: `[BAD_INPUT] Unknown tool: ${name}` }], isError: true };
  }
  try {
    const text = await fn(args || {});
    return { content: [{ type: "text", text }] };
  } catch (err) {
    return { content: [{ type: "text", text: describeFailure(err) }], isError: true };
  }
}

/* ------------------------------------------------------------- JSON-RPC */

const rpcResult = (id, result) => ({ jsonrpc: "2.0", id, result });
const rpcError = (id, code, message) => ({ jsonrpc: "2.0", id, error: { code, message } });

async function handleRpc(msg) {
  const { id, method, params } = msg || {};

  switch (method) {
    case "initialize": {
      const asked = params?.protocolVersion;
      const version = SUPPORTED_PROTOCOLS.includes(asked) ? asked : DEFAULT_PROTOCOL;
      return rpcResult(id, {
        protocolVersion: version,
        capabilities: { tools: { listChanged: false } },
        serverInfo: SERVER_INFO,
        instructions:
          "네이버 블로그/뉴스/카페/플레이스 본문을 가져오는 서버입니다. 검색으로 URL을 찾고 read 도구로 본문을 읽으세요.",
      });
    }
    case "tools/list":
      return rpcResult(id, { tools: TOOLS });
    case "tools/call": {
      const res = await callTool(params?.name, params?.arguments);
      return rpcResult(id, res);
    }
    case "ping":
      return rpcResult(id, {});
    case "resources/list":
      return rpcResult(id, { resources: [] });
    case "prompts/list":
      return rpcResult(id, { prompts: [] });
    default:
      // Notifications carry no id and expect no reply.
      if (id === undefined || id === null) return null;
      return rpcError(id, -32601, `Method not found: ${method}`);
  }
}

const json = (body, status = 200, extra = {}) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json", ...CORS, ...extra },
  });

const LANDING = `<!doctype html><meta charset="utf-8">
<title>Naver Content MCP</title>
<style>body{font:15px/1.7 system-ui,sans-serif;max-width:44rem;margin:3rem auto;padding:0 1.2rem}
code{background:#f3f4f6;padding:.15em .4em;border-radius:4px}</style>
<h1>Naver Content MCP</h1>
<p>Authless remote MCP server. Add this URL as a custom connector:</p>
<p><code id="u"></code></p>
<p>Tools: naver_blog_search, naver_blog_read, naver_news_search, naver_news_read,
naver_cafe_search, naver_place_reviews.</p>
<script>document.getElementById('u').textContent=location.origin+'/mcp'</script>`;

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, "") || "/";

    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });

    if (path === "/health") {
      return json({ ok: true, server: SERVER_INFO, tools: TOOLS.map((t) => t.name) });
    }

    if (path === "/" && request.method === "GET") {
      return new Response(LANDING, { headers: { "Content-Type": "text/html; charset=utf-8", ...CORS } });
    }

    if (path === "/mcp" || path === "/sse") {
      // Some clients open an SSE stream first; keep it open and idle. All real
      // traffic goes over POST, which is what the Streamable HTTP spec allows.
      if (request.method === "GET") {
        const stream = new ReadableStream({
          start(controller) {
            controller.enqueue(new TextEncoder().encode(": connected\n\n"));
          },
        });
        return new Response(stream, {
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-store",
            Connection: "keep-alive",
            ...CORS,
          },
        });
      }

      if (request.method === "DELETE") return new Response(null, { status: 204, headers: CORS });

      if (request.method !== "POST") {
        return json({ error: "Method not allowed" }, 405);
      }

      let payload;
      try {
        payload = await request.json();
      } catch {
        return json(rpcError(null, -32700, "Parse error"), 400);
      }

      // A client may batch requests in an array.
      if (Array.isArray(payload)) {
        const out = [];
        for (const msg of payload) {
          const r = await handleRpc(msg);
          if (r) out.push(r);
        }
        return out.length ? json(out) : new Response(null, { status: 202, headers: CORS });
      }

      const response = await handleRpc(payload);
      if (!response) return new Response(null, { status: 202, headers: CORS });

      // Reply as SSE when the client asked for a stream, otherwise plain JSON.
      const accept = request.headers.get("Accept") || "";
      if (accept.includes("text/event-stream")) {
        const body = `event: message\ndata: ${JSON.stringify(response)}\n\n`;
        return new Response(body, {
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-store",
            ...CORS,
          },
        });
      }
      return json(response);
    }

    return json({ error: "Not found", try: "/mcp" }, 404);
  },
};
